arguments.command:
TOPIC='數位健康；僅列出過去 1 天內的期刊文章與連結。輸出為繁體中文，清單式：每項包含標題、期刊名稱、發表日期、DOI/連結。'
mkdir -p artifacts/4666176840 && 
if [ -n "$GEMINI_API_KEY" ] || [ -n "$GOOGLE_API_KEY" ]; then 
  echo "API key found, running live research (this may take minutes)..." >&2; 
  node .agents/skills/gemini-deep-researcher/scripts/research.js "$TOPIC" > artifacts/4666176840/result.md; 
else 
  echo "No API key found — performing dry run and saving payload." >&2; 
  DEEP_RESEARCHER_DRY_RUN=1 node .agents/skills/gemini-deep-researcher/scripts/research.js "$TOPIC" > /tmp/deep_payload.json; 
  echo "# Deep Researcher Dry Run — 無法呼叫 API，已輸出請求載荷" > artifacts/4666176840/result.md; 
  echo "" >> artifacts/4666176840/result.md; 
  echo "以下為發送給 Deep Researcher agent 的 JSON 載荷（乾跑模式）。若要取得實際研究結果，請在環境中設定 GEMINI_API_KEY 或 GOOGLE_API_KEY 並重新執行。" >> artifacts/4666176840/result.md; 
  echo "" >> artifacts/4666176840/result.md; 
  echo '```json' >> artifacts/4666176840/result.md; 
  cat /tmp/deep_payload.json >> artifacts/4666176840/result.md; 
  echo '```' >> artifacts/4666176840/result.md; 
fi; 
echo "Done."

